// Owned complete-source type reader. Subject source and initializers are never executed.
package main
import("bytes";"encoding/json";"fmt";"go/ast";"go/format";"go/importer";"go/parser";"go/token";"go/types";"io";"os";"path/filepath";"sort")
type Request struct {Package string `json:"package"`; Files []string `json:"files"`; Exports map[string]string `json:"exports"`}
func render(fs *token.FileSet,n ast.Node)string{var b bytes.Buffer;if e:=format.Node(&b,fs,n);e!=nil{panic(e)};return b.String()}
func main(){if len(os.Args)!=2{panic("one explicit owned request path required")};raw,e:=os.ReadFile(os.Args[1]);if e!=nil{panic(e)};var r Request;if e=json.Unmarshal(raw,&r);e!=nil{panic(e)};if len(r.Files)<1||len(r.Files)>32{panic("bounded full package source list required")}
fs:=token.NewFileSet();files:=[]*ast.File{};for _,path:=range r.Files{f,e:=parser.ParseFile(fs,path,nil,parser.ParseComments);if e!=nil{panic(e)};files=append(files,f)}
lookup:=func(name string)(io.ReadCloser,error){path,ok:=r.Exports[name];if !ok{return nil,fmt.Errorf("unregistered export import %s",name)};return os.Open(path)}
info:=&types.Info{Defs:map[*ast.Ident]types.Object{},Uses:map[*ast.Ident]types.Object{},Types:map[ast.Expr]types.TypeAndValue{}}
conf:=types.Config{Importer:importer.ForCompiler(fs,"gc",lookup),Sizes:types.SizesFor("gc","arm64"),GoVersion:"go1.16"};pkg,e:=conf.Check(r.Package,fs,files,info);if e!=nil{panic(e)}
constants:=[]map[string]any{};variables:=[]map[string]any{};functions:=[]map[string]any{}
for _,name:=range pkg.Scope().Names(){obj:=pkg.Scope().Lookup(name);position:=fs.Position(obj.Pos());base:=map[string]any{"name":name,"type":types.TypeString(obj.Type(),func(p *types.Package)string{return p.Name()}),"exported":obj.Exported(),"file":filepath.Base(position.Filename),"line":position.Line}
switch value:=obj.(type){case *types.Const:base["exact_constant_value"]=value.Val().ExactString();base["kind"]="constant";constants=append(constants,base);case *types.Var:base["kind"]="variable";base["immutable_value_claimed"]=false;variables=append(variables,base);case *types.Func:base["kind"]="function";functions=append(functions,base)}}
maps:=[]map[string]any{};imports:=map[string]bool{};initializers:=[]map[string]any{}
for _,file:=range files{for _,imp:=range file.Imports{imports[imp.Path.Value]=true};for _,decl:=range file.Decls{if fn,ok:=decl.(*ast.FuncDecl);ok&&fn.Name.Name=="init"{initializers=append(initializers,map[string]any{"file":filepath.Base(fs.Position(fn.Pos()).Filename),"first_line":fs.Position(fn.Pos()).Line,"last_line":fs.Position(fn.End()).Line,"quote":render(fs,fn)})};gen,ok:=decl.(*ast.GenDecl);if !ok||gen.Tok!=token.VAR{continue};for _,spec:=range gen.Specs{vs,ok:=spec.(*ast.ValueSpec);if !ok||len(vs.Names)!=1||len(vs.Values)!=1{continue};lit,ok:=vs.Values[0].(*ast.CompositeLit);if !ok{continue};if _,ok:=info.Types[lit].Type.(*types.Map);!ok{continue};entries:=[]map[string]any{};for _,elt:=range lit.Elts{kv,ok:=elt.(*ast.KeyValueExpr);if !ok{panic("non-key/value map initializer")};key:=info.Types[kv.Key];if key.Value==nil{panic("nonconstant key outside static initializer profile")};entry:=map[string]any{"key_constant":key.Value.ExactString(),"key_source":render(fs,kv.Key),"value_source":render(fs,kv.Value),"line":fs.Position(kv.Pos()).Line};if value:=info.Types[kv.Value];value.Value!=nil{entry["value_constant"]=value.Value.ExactString()};if ident,ok:=kv.Value.(*ast.Ident);ok{if object:=info.Uses[ident];object!=nil{entry["value_object_kind"]=fmt.Sprintf("%T",object);entry["value_object_name"]=object.Name();entry["value_object_type"]=types.TypeString(object.Type(),func(p *types.Package)string{return p.Name()})}};entries=append(entries,entry)};maps=append(maps,map[string]any{"name":vs.Names[0].Name,"file":filepath.Base(fs.Position(vs.Pos()).Filename),"first_line":fs.Position(vs.Pos()).Line,"last_line":fs.Position(vs.End()).Line,"entries":entries,"scope":"Written map initializer, not immutable later runtime contents or pointed-to integer values"})}}}
importList:=[]string{};for name:=range imports{importList=append(importList,name)};sort.Strings(importList)
if e:=json.NewEncoder(os.Stdout).Encode(map[string]any{"package":pkg.Path(),"static_go_version":"go1.16","sizes":"gc/arm64","constants":constants,"variables":variables,"functions":functions,"map_initializers":maps,"explicit_initializers":initializers,"imports":importList,"subject_source_executed":false,"mutable_globals_certified_immutable":false});e!=nil{panic(e)}}
